    (* [comment removed for export] *)
    Section JQ.
      Variables (mm : word -> option byte).
      Hypothesis MIm : mem_inv bsegs mm.
      Hypothesis STm : stk bsegs mm lo (bv_unsigned sp + -2128).
      Hypothesis FRm : FRAME mm.
      Hypothesis FR2m : rw_cells bsegs mm (bv_unsigned sp + -2128) [CB 2080 fj].
      Hypothesis MU : munch W m2 mm.
      Hypothesis WM : wmono bsegs m2 mm.
      Hypothesis ACm : ACONST mm.
      Hypothesis RP : 0 < r <= 2^40.
      Hypothesis RC : r <= cnt.
      Hypothesis ACC : accessible mm buf r.
      Hypothesis INM : in_app_mem buf (buf + r).
      Hypothesis N64 : 1 <= r <= 64.
      Hypothesis SVm : stk bsegs mm (sh (hull_lo buf)) (sh (hull_hi (buf + r))).

      Let LAY := ACONST_layout mm ACm.

